using System;
using System.Collections.Generic;
using System.Threading;

/// <summary>
/// Migrated EventProcessor using cooperative cancellation (CancellationToken)
/// instead of Thread.Interrupt / Thread.Abort, which throw
/// PlatformNotSupportedException in .NET 6+.
/// </summary>
public class EventProcessor : IDisposable
{
    private readonly ManualResetEvent _newEvent = new ManualResetEvent(false);
    private readonly Queue<string> _queue = new Queue<string>();
    private Thread? _thread;
    private readonly object _lock = new object();
    private readonly CancellationTokenSource _cts = new CancellationTokenSource();
    private bool _disposed;

    public void Start()
    {
        _thread = new Thread(RunLoop);
        _thread.Start();
    }

    private void RunLoop()
    {
        var token = _cts.Token;
        var handles = new WaitHandle[] { _newEvent, token.WaitHandle };

        while (!token.IsCancellationRequested)
        {
            // WaitAny returns the index of the handle that was signaled.
            // Index 0 = _newEvent (new work), Index 1 = cancellation requested.
            int signaled = WaitHandle.WaitAny(handles);
            if (signaled == 1)
                break; // cancellation token was signaled — exit cleanly

            _newEvent.Reset();

            string? item = null;
            lock (_lock)
            {
                if (_queue.Count > 0)
                    item = _queue.Dequeue();
            }

            if (item is not null)
                Handle(item);
        }
    }

    public void Enqueue(string item)
    {
        lock (_lock) { _queue.Enqueue(item); }
        _newEvent.Set();
    }

    public void Stop()
    {
        // Signal cooperative cancellation — wakes RunLoop via WaitHandle.WaitAny
        _cts.Cancel();

        // Wait for the thread to finish gracefully
        _thread?.Join(5000);
    }

    private void Handle(string item)
    {
        // Processing logic here
    }

    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;
        Stop();
        _cts.Dispose();
        _newEvent.Dispose();
    }
}

